mkdir -p /tmp/check; cat > /tmp/check/lw_check.py <<'EOF'
"""Independent check of a Litware schedule against docs/LITWARE_SOW.md, from raw files only."""
import sys, math, csv, re
from datetime import datetime, timedelta, timezone, date
from zoneinfo import ZoneInfo
from collections import defaultdict

week, data, sched_path = sys.argv[1], sys.argv[2], sys.argv[3]
runbook = sys.argv[4] if len(sys.argv) > 4 else None
Z = ZoneInfo("Europe/London"); STEP = timedelta(minutes=20)
SLA = {"priority": (0.9, 30), "standard": (0.8, 30), "email": (0.8, 300)}
TPL = {"D8": [(9, 17)], "L8": [(13, 21)], "P6a": [(7, 13)], "P6b": [(15, 21)], "P4": [(10, 14)], "S44": [(8, 12), (16, 20)]}

def pw(a, n):
    # Erlang B recursion -> C
    b = 1.0
    for k in range(1, n + 1):
        b = a * b / (k + a * b)
    return n * b / (n - a * (1 - b))

def sl(a, n, aht, t):
    if a <= 0: return 1.0
    if n <= a: return 0.0
    return 1 - pw(a, n) * math.exp(-(n - a) * t / aht)

def req(vol, aht, q):
    if vol <= 0: return 0
    a = vol / 1200 * aht
    n = max(1, math.floor(a) + 1 if a == int(a) else math.ceil(a))
    while not (sl(a, n, aht, SLA[q][1]) >= SLA[q][0] and a / n <= 0.85): n += 1
    return n

y, w = week.split("-W"); mon = date.fromisocalendar(int(y), int(w), 1)
ws = datetime(mon.year, mon.month, mon.day, tzinfo=Z).astimezone(timezone.utc)
nm = mon + timedelta(days=7); we = datetime(nm.year, nm.month, nm.day, tzinfo=Z).astimezone(timezone.utc)
grid = []; t = ws
while t < we: grid.append(t); t += STEP
R = defaultdict(int); vol = defaultdict(float)
for r in csv.DictReader(open(data)):
    lab = r["interval_end_local"]
    d = datetime.strptime(lab.replace(" 24:00", " 00:00"), "%Y-%m-%d %H:%M") + (timedelta(days=1) if lab.endswith("24:00") else timedelta())
    sign = 1 if r["utc_offset"][0] == "+" else -1; hh, mm = map(int, r["utc_offset"][1:].split(":"))
    end = (d - sign * timedelta(hours=hh, minutes=mm)).replace(tzinfo=timezone.utc)
    st = end - STEP
    if ws <= st < we:
        R[(r["queue"], st)] = req(float(r["volume"]), float(r["aht_sec"]), r["queue"]); vol[(r["queue"], st)] = float(r["volume"])

def loc_h(t): l = t.astimezone(Z); return l.hour + l.minute / 60
def operating(t, q, email_close=21): return 7 <= loc_h(t) < (email_close if q == "email" else 21)

def P(s): return datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
rows = list(csv.DictReader(open(sched_path)))
roster = {r["agent_id"]: (r["contract"], set(r["skills"].split(";"))) for r in csv.DictReader(open("/app/data/agents/litware.csv"))}
gross = defaultdict(int); brk = defaultdict(int)
shifts = defaultdict(list)  # (agent, localday) -> rows
viol = defaultdict(list)
for r in rows:
    s, e = P(r["segment_start_utc"]), P(r["segment_end_utc"])
    r["s"], r["e"] = s, e
    r["b"] = P(r["break_start_utc"]) if r["break_start_utc"] else None
    shifts[(r["agent_id"], s.astimezone(Z).date())].append(r)
    for t in grid:
        if s <= t < e:
            gross[(r["queue"], t)] += 1
            if r["b"] and int(r["break_minutes"]) and r["b"] < t + STEP and t < r["b"] + timedelta(minutes=int(r["break_minutes"])):
                brk[(r["queue"], t)] += 1
net = lambda q, t: gross[(q, t)] - brk[(q, t)]
Q = ["priority", "standard", "email"]
# infeasible (email < 09:00 with required > 0; or more required than skilled agents)
skilled = {q: sum(1 for c, sk in roster.values() if q in sk) for q in Q}
infeas = sorted([(q, t) for q in Q for t in grid if R[(q, t)] > 0 and ((q == "email" and loc_h(t) < 9) or R[(q, t)] > skilled[q] or not 7 <= loc_h(t) < 21)], key=lambda k: (k[1], Q.index(k[0])))
infs = set(infeas)
hours = sum((r["e"] - r["s"]).total_seconds() for r in rows) / 3600
reqh = sum(R.values()) / 3
print(f"intervals {len(grid)} sched_h {hours:.1f} req_h {reqh:.1f} ratio {hours/reqh:.4f} (<=1.45: {hours <= 1.45*reqh + 1e-9})")
att = {}
for q in Q:
    for close in ([21, 19] if q == "email" else [21]):
        ops = [t for t in grid if operating(t, q, close) and (q, t) not in infs]
        met = sum(1 for t in ops if net(q, t) >= R[(q, t)])
        att[(q, close)] = met / len(ops)
        print(f"  {q} close {close}: {met}/{len(ops)} = {met/len(ops):.3f}")
under = sum(max(0, R[(q, t)] - net(q, t)) for q in Q for t in grid if (q, t) not in infs) / 3
print(f"understaffed {under:.1f} exceptions {len(infeas)} agents {len({r['agent_id'] for r in rows})}")
# rules
per_agent = defaultdict(list)
for (a, d), rs in shifts.items():
    rs.sort(key=lambda r: r["s"]); per_agent[a].append((d, rs))
    tids = {r["template_id"] for r in rs}; tid = rs[0]["template_id"]
    c, sk = roster[a]
    exp = [(datetime(d.year, d.month, d.day, tzinfo=Z) + timedelta(hours=x)).astimezone(timezone.utc) for seg in TPL.get(tid, []) for x in seg]
    got = [x for r in rs for x in (r["s"], r["e"])]
    if len(tids) != 1 or tid not in TPL or exp != got: viol["2.10 template"].append((a, d))
    if len(rs) > 1 and c != "PT": viol["2.2 split"].append((a, d))
